/bin/zsh -lc "./run_python smoke.py && ./run_python - <<'PY'
import app

# UTF-8 may split at any byte boundary.
wire = '{\"event\":\"token\",\"text\":\"Aé🙂\\\\tB\"}\\n{\"event\":\"done\"}\\n'.encode()
for split in range(len(wire) + 1):
    parser = app.EventStream()
    events = parser.feed(wire[:split]) + parser.feed(wire[split:])
    assert events == [
        {\"event\": \"token\", \"text\": \"Aé🙂\\tB\"},
        {\"event\": \"done\", \"text\": \"Aé🙂\\tB\", \"characters\": 5, \"words\": 2},
    ]
    assert parser.state == \"DONE\" and parser.finish() == []
assert app.text_metrics(\"a\\u2003b\\n\") == {\"characters\": 4, \"words\": 2}

# Large chunks can contain many frames; each individual frame is exactly at the bound.
frame = b'{\"event\":\"token\",\"text\":\"\"}'
parser = app.EventStream(max_buffer=len(frame))
assert len(parser.feed((frame + b\"\\n\") * 50)) == 50
assert parser.buffered_bytes == 0

# A terminal event followed by any bytes in that same chunk fails the stream.
for terminal in (b'{\"event\":\"done\"}\\n', b'{\"event\":\"error\",\"message\":\"x\"}\\n'):
    parser = app.EventStream()
    try:
        parser.feed(terminal + b\"x\")
    except app.StreamError:
        pass
    else:
        raise AssertionError(\"accepted bytes after terminal event\")
    assert parser.state == \"FAILED\" and parser.buffered_bytes == 0

# Invalid UTF-8/JSON/schema, empty frames, and overlong frames fail and clear state.
for wire, limit in (
    (b'\\xff\\n', 8),
    (b'{\\n', 8),
    (b'{\"event\":\"done\",\"event\":\"done\"}\\n', 64),
    (b'{\"event\":\"wat\"}\\n', 64),
    (b'\\n', 8),
    (b'1234', 3),
):
    parser = app.EventStream(max_buffer=limit)
    try:
        parser.feed(wire)
    except app.StreamError:
        pass
    else:
        raise AssertionError(\"invalid stream accepted: \" + repr(wire))
    assert parser.state == \"FAILED\" and parser.buffered_bytes == 0
    try:
        parser.finish()
    except app.StreamError:
        pass
    else:
        raise AssertionError(\"failed parser accepted finish\")

# EOF while open is failure, even with no pending bytes.
for pending in (b\"\", b'{\"event\":'):
    parser = app.EventStream()
    if pending:
        parser.feed(pending)
    try:
        parser.finish()
    except app.StreamError:
        pass
    else:
        raise AssertionError(\"premature EOF accepted\")
    assert parser.state == \"FAILED\" and parser.buffered_bytes == 0
print(\"edge checks passed\")
PY"
